from sqlalchemy import Column, Integer, String, Text, DateTime, JSON, Float
from sqlalchemy.sql import func
from pgvector.sqlalchemy import Vector
from .database import Base

class Meme(Base):
    __tablename__ = "memes"

    id = Column(Integer, primary_key=True, index=True)
    source_url = Column(String, unique=True, index=True, nullable=True)
    r2_key = Column(String, unique=True, nullable=False)
    
    # Textual metadata generated by Vision LLM
    text_caption = Column(Text, nullable=True)
    film_series_name = Column(String, nullable=True)
    year = Column(Integer, nullable=True)
    emotion = Column(String, nullable=True)
    situation = Column(Text, nullable=True)
    
    # Technical Deduplication Fields
    image_hash = Column(String, index=True, nullable=True)
    
    # Vector Embedding
    embedding = Column(Vector(1536)) # Assuming OpenAI embeddings dimensionality (1536)

    created_at = Column(DateTime(timezone=True), server_default=func.now())
    updated_at = Column(DateTime(timezone=True), onupdate=func.now())
